#include <bits/stdc++.h>
using namespace std;
const int MOD=1e9+7;
const int LIMIT=1<<20;
int n,mask_end,final_result,p1_accum[LIMIT],p2_accum[LIMIT];
int flag_grid[10][10],a_grid[10][10],h_map[10][10][10];

int power_mod(int base, int exp) {
    int res=1;
    while (exp > 0) {
        if (exp & 1) res=1LL*res*base%MOD;
        base=1LL*base*base%MOD;
        exp>>=1;
    }
    return res;
}

int mod_inverse(int x) { return power_mod(x,MOD-2); }

bool check_triplet(int x,int y,int z) {
    int arr[3]={x,y,z},perm[3]={0,1,2};
    do {
        if (flag_grid[arr[perm[0]]][1] && flag_grid[arr[perm[1]]][2] && flag_grid[arr[perm[2]]][3]) return true;
    } while (next_permutation(perm,perm+3));
    return false;
}

void process_first(int P,int x,int y) {
    if (x==7 && y==1) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (check_triplet(i,j,k)) {
                        int X=1;
                        while (X==i || X==j || X==k) X++;
                        int Y=X+1;
                        while (Y==i || Y==j || Y==k) Y++;
                        int Z=Y+1;
                        while (Z==i || Z==j || Z==k) Z++;
                        state|=h_map[X][Y][Z];
                    }
        p1_accum[state]=(p1_accum[state]+P)%MOD;
        return;
    }
    flag_grid[x][y]=1;
    if (y==3) process_first(1LL*P*a_grid[x][y]%MOD,x+1,1);
    else process_first(1LL*P*a_grid[x][y]%MOD,x,y+1);
    flag_grid[x][y]=0;
    if (y==3) process_first(1LL*P*(MOD+1-a_grid[x][y])%MOD,x+1,1);
    else process_first(1LL*P*(MOD+1-a_grid[x][y])%MOD,x,y+1);
}

void process_second(int P,int x,int y) {
    if (x==7 && y==4) {
        int state=0;
        for (int i=1; i<=6; i++)
            for (int j=i+1; j<=6; j++)
                for (int k=j+1; k<=6; k++) 
                    if (check_triplet(i,j,k)) state|=h_map[i][j][k];
        p2_accum[state]=(p2_accum[state]+P)%MOD;
        final_result=(final_result+1LL*p1_accum[mask_end^state]*P)%MOD;
        return;
    }
    flag_grid[x][y-3]=1;
    if (y==6) process_second(1LL*P*a_grid[x][y]%MOD,x+1,4);
    else process_second(1LL*P*a_grid[x][y]%MOD,x,y+1);
    flag_grid[x][y-3]=0;
    if (y==6) process_second(1LL*P*(MOD+1-a_grid[x][y])%MOD,x+1,4);
    else process_second(1LL*P*(MOD+1-a_grid[x][y])%MOD,x,y+1);
}

int main() {
    scanf("%d",&n);
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            scanf("%d",&a_grid[i][j]),a_grid[i][j]=1LL*a_grid[i][j]*mod_inverse(100)%MOD;
    for (int i=n+1; i<=6; i++) a_grid[i][i]=1;
    int total=0;
    for (int i=1; i<=6; i++)
        for (int j=i+1; j<=6; j++)
            for (int k=j+1; k<=6; k++) 
                h_map[i][j][k]=1<<total++;
    process_first(1,1,1);
    mask_end=(1<<20)-1;
    for (int i=0; i<=19; i++)
        for (int j=0; j<=mask_end; j++) 
            if (j>>i&1) p1_accum[j]=(p1_accum[j]+p1_accum[j^1<<i])%MOD;
    process_second(1,1,4);
    final_result=(MOD+1-final_result)%MOD;
    printf("%d\n",final_result);
    return 0;
}
